import com.badlogic.gdx.backends.headless.HeadlessApplicationConfiguration;

public final class HeadlessConfigLauncher {
    private HeadlessConfigLauncher() {
    }

    public static void main(String[] args) throws InterruptedException {
        String configPath;
        try {
            configPath = parseConfigPath(args);
        } catch (InvalidConfigException e) {
            System.err.println("Error: invalid config: " + e.getMessage());
            System.err.flush();
            System.exit(1);
            return;
        }

        ConfigSummaryApplication listener = new ConfigSummaryApplication(configPath);
        HeadlessApplicationConfiguration configuration = new HeadlessApplicationConfiguration();
        configuration.updatesPerSecond = 60;

        HeadlessApplication application = new HeadlessApplication(listener, configuration);
        application.getApplicationListener();
        application.getMainLoopThread().join();

        System.out.flush();
        System.err.flush();
        if (!listener.isSuccessful()) {
            System.exit(1);
        }
    }

    private static String parseConfigPath

